-- Resources content for the recorded-in-DAD status (CLAUDE.md, "Resources
-- stay in step with the code"). Content only; the schema change is
-- 20261002160000.

select private.rc_release_guide(
  p_slug => 'underwriting-copy-in-dad',
  p_tool_key => 'underwriting',
  p_title => 'Copy in DAD',
  p_summary => 'Each message''s DAD cut: the number to record it under, or the existing DAD spot it plays.',
  p_screen_keys => array['underwriting.copy'],
  p_sort_order => 35,
  p_version_note => 'Recorded in DAD',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Every message on file has a DAD cut: the number DAD plays it from. A recorded spot plays its recording. A live read is read by the host when someone is on air, and DAD plays its recorded version in hours with no host."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"New recording"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A new message gets the next free cut when you save it, in the form "},{"type":"text","text":"00548A","marks":[{"type":"bold"}]},{"type":"text","text":". Record the message into DAD under that number."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Messages that were on file before cuts existed kept their old number where only one current message used it, so Loyalty Credit Union's copy 1 is "},{"type":"text","text":"00013A","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"To use another number, choose "},{"type":"text","text":"Use a different cut","marks":[{"type":"bold"}]},{"type":"text","text":" on the copy's edit page. A cut belongs to one message, so a number already in use is refused."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Recorded in DAD"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A new cut isn't in DAD until someone records the message under it. The copy page shows "},{"type":"text","text":"To record","marks":[{"type":"bold"}]},{"type":"text","text":" until production marks it with "},{"type":"text","text":"Mark recorded","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The "},{"type":"text","text":"To record","marks":[{"type":"bold"}]},{"type":"text","text":" filter in the copy library, and the dashboard's "},{"type":"text","text":"To record in DAD","marks":[{"type":"bold"}]},{"type":"text","text":" tile, list every message that can still air and isn't recorded. Production can mark each one from that list."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Changing a message's cut, or the wording of a message under a new cut, clears the mark, since the recording no longer matches."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A message that plays an existing DAD spot is already recorded."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The DAD log can't be released while a credit in automated hours isn't recorded."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Existing DAD spot"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Some copy asks the host to play a spot that's already in DAD, such as a Learning Minute in the PPA group. Choose "},{"type":"text","text":"Existing DAD spot","marks":[{"type":"bold"}]},{"type":"text","text":" and search DAD's library by cut number or title."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Copy like this starts without a cut. It shows "},{"type":"text","text":"Pick a DAD spot","marks":[{"type":"bold"}]},{"type":"text","text":" in the copy library, and the "},{"type":"text","text":"Needs a DAD cut","marks":[{"type":"bold"}]},{"type":"text","text":" filter lists every message still waiting."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Good to know"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The copy page's "},{"type":"text","text":"Copy","marks":[{"type":"bold"}]},{"type":"text","text":" button puts the cut on the clipboard for pasting into DAD."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"On the rundown, a recorded spot shows the cut the host fires. A live read shows no cut."}]}]}]}]}$body$
);

select private.rc_release_guide(
  p_slug => 'log-dad-log',
  p_tool_key => 'log',
  p_title => 'The DAD log',
  p_summary => 'The file DAD plays automated hours from: what''s in it, what stops it, and how to release it.',
  p_screen_keys => array['log.dad-log'],
  p_sort_order => 46,
  p_version_note => 'Unrecorded cuts block a release',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The DAD log is the file DAD merges into a day's playlist so it plays that day's credits in automated hours. Open it from "},{"type":"text","text":"Today","marks":[{"type":"bold"}]},{"type":"text","text":" with "},{"type":"text","text":"DAD log","marks":[{"type":"bold"}]},{"type":"text","text":". Only breaks in automated hours are in the file; hosted hours are left to the host."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Before releasing"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The bar at the top shades the day's automated hours. Change them on "},{"type":"text","text":"Automated hours","marks":[{"type":"bold"}]},{"type":"text","text":", reached from Programs."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Anything DAD can't play is listed first, with a link to fix it: a message with no DAD cut or not yet recorded in DAD, something only a host can do (a live read written for the rundown, or the weather), copy that isn't approved or is outside its dates, or a break that runs past its window."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A program that airs in automated hours but has no rundown is listed as worth knowing. Its breaks aren't in the file until it has one."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The "},{"type":"text","text":"Table","marks":[{"type":"bold"}]},{"type":"text","text":" shows what DAD will play and when. "},{"type":"text","text":"File","marks":[{"type":"bold"}]},{"type":"text","text":" shows the exact rows."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Releasing"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Traffic releases the day with "},{"type":"text","text":"Release","marks":[{"type":"bold"}]},{"type":"text","text":". It's refused while anything can't play."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Download the release and put it in DAD's import folder. The file is named for the day, such as 100126tWUWF.log."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"If a rundown changes afterwards, the page says the release is out of date. Release again; each release is a new version, and the history keeps every one."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Each item keeps the same spot number in every version."}]}]}]}]}$body$
);

select private.rc_release_note(
  p_slug => 'release-2026-10-02-underwriting-recorded-in-dad',
  p_tool_key => 'underwriting',
  p_released_on => '2026-10-02',
  p_title => 'Copy shows whether it is recorded in DAD',
  p_guide_slugs => array['underwriting-copy-in-dad', 'log-dad-log'],
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A message under a new DAD cut now shows To record until production marks it recorded. The copy library has a To record filter and the dashboard a To record in DAD tile. Changing the cut or the wording clears the mark, and the DAD log won't release a credit that isn't recorded."}]}]}$body$
);
